begin;
create extension if not exists pgtap with schema extensions;
set search_path=workspace,extensions,public;
select no_plan();
select is(has_function_privilege('anon','workspace_private.executive_task_definition(text)','execute'),false,'anon cannot invoke workspace_private.executive_task_definition(text)');
