select ok((select prosecdef from pg_proc where oid='workspace.executive_get_source_permissions_v2()'::regprocedure),'guarded owner rights: workspace.executive_get_source_permissions_v2()');
select is(has_function_privilege('anon','workspace.executive_set_source_permissions_v2(jsonb,jsonb,integer,uuid,boolean,boolean,text)','execute'),false,'anonymous bridge denied: workspace.executive_set_source_permissions_v2(jsonb,jsonb,integer,uuid,boolean,boolean,text)');
