select ok((select prosecdef from pg_proc where oid='workspace.executive_set_source_permissions_v2(jsonb,jsonb,integer,uuid,boolean,boolean,text)'::regprocedure),'guarded owner rights: workspace.executive_set_source_permissions_v2(jsonb,jsonb,integer,uuid,boolean,boolean,text)');
select is(has_function_privilege('anon','workspace.executive_find_sources(text,text,text,text,integer)','execute'),false,'anonymous bridge denied: workspace.executive_find_sources(text,text,text,text,integer)');
