select is(has_function_privilege('authenticated','workspace.executive_review_attention(date,integer,integer)','execute'),true,'authenticated guarded bridge: workspace.executive_review_attention(date,integer,integer)');
select ok((select prosecdef from pg_proc where oid='workspace.executive_review_attention(date,integer,integer)'::regprocedure),'guarded owner rights: workspace.executive_review_attention(date,integer,integer)');
select throws_ok($$select workspace.executive_review_attention(current_date,0,25)$$,'42501',null,'attention needs verified identity');
select throws_ok($$select workspace.executive_find_sources('nonprofit.roadmap','task','',null,20)$$,'42501',null,'task catalog needs verified identity');
select throws_ok($$select workspace.executive_get_source_permissions_v2()$$,'42501',null,'permission view needs verified identity');
select throws_ok($$select workspace.executive_set_source_permissions_v2('[]','[]',0,gen_random_uuid(),true,true,'task-metadata-v1')$$,'42501',null,'permission changes need verified native identity');
select ok((select relrowsecurity from pg_class where oid='workspace_private.executive_source_permissions'::regclass),'permission RLS retained');
select ok((select relrowsecurity from pg_class where oid='workspace_private.executive_source_permission_versions'::regclass),'permission audit RLS retained');
select is(has_table_privilege('authenticated','workspace_private.executive_source_permission_versions','SELECT'),false,'permission audit inaccessible directly');
select * from finish();
rollback;
